// ── Build evidence context for LLM ──────────────────────────
// Extract ONLY verified facts from the analysis result.
// The LLM receives pre-computed data — it does NOT compute anything.

const input = $input.first().json.body;

const evidenceContext = {
  // What the user asked
  user_question: input.query || 'No query provided',

  // Analysis plan
  analysis_type: input.analysis_plan?.analysis_type || input.method || 'unknown',
  aoi: input.aoi_bbox || [],
  event_date: input.event_date || null,

  // Computed statistics (already calculated by Python engine)
  statistics: input.statistics || {},
  change_map_summary: input.change_map_summary || {},

  // Scenes used as evidence
  selected_scenes: (input.selected_scenes || []).map(s => ({
    id: s.item_id || s.id,
    sensor: s.sensor || 'unknown',
    role: s.role || 'unknown',
    datetime: s.datetime || 'unknown',
  })),

  // Processing metadata
  method: input.method || 'unknown',
  confidence: input.confidence || 'unknown',
  limitations: input.limitations || [],
  processing_steps: input.processing_steps || [],

  // Evidence/provenance
  evidence: input.evidence || {},
  analysis_id: input.analysis_id || 'unknown',
};

return [{ json: evidenceContext }];

// ── Validate LLM output ─────────────────────────────────────
// Ensure the LLM returned valid JSON with required fields.
// If invalid, route to human review.

const llmOutput = $input.first().json;
const evidenceContext = $('Build Evidence Context').first().json;

let explanation;
try {
  // Try to parse the LLM output as JSON
  const content = llmOutput.choices?.[0]?.message?.content || llmOutput.text || JSON.stringify(llmOutput);
  explanation = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // LLM returned invalid JSON — route to human review
  return [{
    json: {
      valid: false,
      reason: 'LLM returned invalid JSON: ' + e.message,
      raw_output: llmOutput,
      needs_human_review: true,
    }
  }];
}

// Validate required fields
const requiredFields = ['summary', 'key_findings', 'confidence_statement', 'limitations'];
const missing = requiredFields.filter(f => !explanation[f]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      reason: 'Missing required fields: ' + missing.join(', '),
      raw_output: explanation,
      needs_human_review: true,
    }
  }];
}

// Validate that key_findings is an array
if (!Array.isArray(explanation.key_findings)) {
  return [{
    json: {
      valid: false,
      reason: 'key_findings must be an array',
      raw_output: explanation,
      needs_human_review: true,
    }
  }];
}

// Validate that no measurements exceed what was computed
// (basic sanity check)
if (explanation.affected_area) {
  const computedArea = evidenceContext.change_map_summary?.flood_area_sq_meters;
  if (computedArea && explanation.affected_area.area_sq_meters) {
    const claimed = explanation.affected_area.area_sq_meters;
    if (claimed > computedArea * 2) {
      return [{
        json: {
          valid: false,
          reason: 'Claimed area (' + claimed + ') exceeds computed area (' + computedArea + ') by more than 2x',
          raw_output: explanation,
          needs_human_review: true,
        }
      }];
    }
  }
}

// Validation passed
return [{
  json: {
    valid: true,
    explanation: explanation,
    needs_human_review: false,
  }
}];

// ── Generate Report ──────────────────────────────────────────
// Build a formatted report from the validated explanation.

const input = $input.first().json;
const explanation = input.explanation;
const evidenceContext = $('Build Evidence Context').first().json;

// Build formatted report
const report = {
  // Analysis metadata
  analysis_id: evidenceContext.analysis_id,
  generated_at: new Date().toISOString(),

  // Explanation content
  summary: explanation.summary,
  key_findings: explanation.key_findings || [],
  affected_area: explanation.affected_area || evidenceContext.change_map_summary,
  spatial_findings: explanation.spatial_findings || {},

  // Confidence and limitations
  confidence_statement: explanation.confidence_statement,
  limitations: explanation.limitations || evidenceContext.limitations,

  // Evidence trail
  evidence_references: explanation.evidence_references || [],
  scenes_used: evidenceContext.selected_scenes,

  // Provenance
  method: evidenceContext.method,
  computed_statistics: evidenceContext.statistics,
  processing_steps: evidenceContext.processing_steps,

  // Human review flag
  human_review: false,
};

return [{ json: report }];

// ── Human Review Branch ─────────────────────────────────────
// When validation fails, package for human review.

const input = $input.first().json;
const evidenceContext = $('Build Evidence Context').first().json;

const reviewPackage = {
  analysis_id: evidenceContext.analysis_id,
  generated_at: new Date().toISOString(),

  human_review: true,
  review_reason: input.reason || 'Validation failed',

  // Provide the raw data for human interpretation
  raw_llm_output: input.raw_output,
  evidence_context: evidenceContext,

  // Suggest a default explanation
  suggested_explanation: {
    summary: 'This analysis result requires human review before publication. The automated explanation could not be validated.',
    key_findings: [{
      finding: 'Automated analysis completed but explanation validation failed',
      evidence_id: evidenceContext.analysis_id,
      confidence: 'requires_review',
    }],
    affected_area: evidenceContext.change_map_summary,
    confidence_statement: 'Pending human review',
    limitations: [
      ...(evidenceContext.limitations || []),
      'Automated explanation validation failed: ' + (input.reason || 'unknown'),
    ],
    evidence_references: evidenceContext.selected_scenes.map(s => s.item_id || s.id),
  },
};

return [{ json: reviewPackage }];
